/**
 * Normalize 2B orchestrator input (JSON-only)
 */
const input = $json || {};
const body = input.body && input.body !== input ? input.body : input;

const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

const orderId = pick(input.orderId, input.amazonOrderId, body.orderId, body.amazonOrderId, null);
if (!orderId) throw new Error('2B main: orderId is required');

// 2A manifest URL
let manifestUrl = pick(input.manifestUrl, input.originalManifestUrl, body.manifestUrl, body.originalManifestUrl, null);
if (!manifestUrl) {
  const base = pick(input.backendUrl, body.backendUrl, 'https://admin.littleherolabs.com');
  manifestUrl = `${base}/api/manifests/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`;
}

const backendUrl = pick(input.backendUrl, body.backendUrl, 'https://admin.littleherolabs.com');
const callbackUrl = pick(input.callbackUrl, body.callbackUrl, `${backendUrl}/webhook/2b-callback`);

// n8n Cloud-friendly: pass sw1 workflow id in the request payload (or set it directly in the Execute Workflow node UI)
const sw1WorkflowId = pick(input.sw1WorkflowId, body.sw1WorkflowId, null);

const batchSize = Math.max(1, Math.min(3, Number(pick(input.batchSize, body.batchSize, 1)) || 1));
const force = !!pick(input.force, body.force, false);

return [{ json: { orderId, backendUrl, manifestUrl, callbackUrl, sw1WorkflowId, batchSize, force } }];

/**
 * Build pose worklist (idempotent + replacement-aware)
 * Async mode: we only trigger s2B-sw1 and return.
 */
const manifest2a = $json || {};
if (!manifest2a.schema) throw new Error('2B main: expected manifest JSON from Download 2A Manifest');

// Recover context from Normalize node (HTTP nodes overwrite input)
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const orderId = ctx.orderId || manifest2a.order?.amazonOrderId || manifest2a.order?.orderId;
const characterHash = manifest2a.characterHash || manifest2a.order?.characterHash || null;
if (!orderId) throw new Error('2B main: orderId missing after manifest download');
if (!characterHash) throw new Error('2B main: characterHash missing');

const approved = (manifest2a.entries || []).filter(e => e?.approved && e?.status === 'approved');
if (!approved.length) return [{ json: { orderId, characterHash, scheduled: 0, reason: 'NO_APPROVED_POSES' } }];

// Existing 2B manifest (optional) from the previous node
let existing2b = null;
try {
  const maybe = $items('Download 2B Manifest (optional)', 0, $runIndex)?.[0]?.json;
  if (maybe && maybe.schema === 'lhb.run-manifest@v2.0') existing2b = maybe;
} catch {}

const existingEntries = Array.isArray(existing2b?.entries) ? existing2b.entries : [];
const existingByPose = new Map(existingEntries.map(e => [Number(e.poseNumber), e]));

// NOTE: existing 2B manifest lookup occurs in callback for MVP to keep orchestrator lean
// Idempotency can still be applied in callback using sourceApprovedKey/sourceReplacedAt.

const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
const callbackUrl = ctx.callbackUrl;
const force = !!ctx.force;

let skippedCount = 0;
let skippedByBriaStatus = 0;
let skippedBy2BManifest = 0;

const work = approved
  .filter(p => {
    if (force) return true;
    const poseNum = Number(p?.poseNumber);

    // Check 2A manifest for existing Bria status (prevent duplicate submissions)
    const hasBriaStatus = !!(p.briaStatusUrl || p.briaRequestId);
    if (hasBriaStatus) {
      console.log(`✓ Pose ${poseNum}: Already has Bria status, skipping submission`);
      skippedByBriaStatus++;
      skippedCount++;
      return false; // Skip - already submitted
    }

    // Existing 2B manifest check (keep as-is)
    const ex = existingByPose.get(poseNum);
    if (!ex) return true;
    const srcKey = p.approvedKey || null;
    const srcReplacedAt = p.replacedAt || null;
    const srcReplacementCount = Number(p.replacementCount || 0);
    const done = !!(
      ex.bgRemovedKey &&
      String(ex.briaStatus || '').toLowerCase() === 'completed' &&
      (ex.sourceApprovedKey || null) === srcKey &&
      ((ex.sourceReplacedAt || null) === srcReplacedAt || Number(ex.sourceReplacementCount || 0) === srcReplacementCount)
    );
    if (done) {
      skippedBy2BManifest++;
      skippedCount++;
    }
    return !done;
  })
  .map(p => ({
  orderId,
  characterHash,
  poseNumber: p.poseNumber,
  approvedKey: p.approvedKey,
  replacedAt: p.replacedAt || null,
  replacementCount: Number(p.replacementCount || 0),
  manifest2aUrl: ctx.manifestUrl || null,
  backendUrl,
  callbackUrl,
  force
}));

// If all poses were skipped, emit a summary item instead of empty array
if (work.length === 0 && approved.length > 0) {
  return [{ json: { 
    orderId, 
    characterHash, 
    scheduled: 0, 
    reason: 'ALL_POSES_ALREADY_PROCESSED',
    totalApproved: approved.length,
    skippedByBriaStatus,
    skippedBy2BManifest,
    skippedTotal: skippedCount
  } }];
}

// Emit one item per pose for SplitInBatches
return work.map(w => ({ json: w }));

/**
 * Final response payload (does not wait for workers).
 */
const items = $items('Build Worklist', 0, $runIndex) || [];
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}
return [{ json: { orderId: ctx.orderId, scheduled: items.length, callbackUrl: ctx.callbackUrl, batchSize: ctx.batchSize } }];
